/**
 * The Municipality of Anchorage's boundary as GeoJSON, with helpers to test a
 * coordinate against it and to find its bounding box. The Airbnb search covers
 * that bounding box, which also takes in Hope, Palmer and Wasilla, so the
 * Airbnb scrape keeps only the listings inside the boundary itself.
 *
 * `municipality.geojson` is generated by `municipality.sql`, which documents
 * the source and why the boundary is padded by 1 km. Regenerate it rather
 * than editing it by hand. `test/muni_geography/municipality.test.ts` checks
 * places on both sides of the line.
 */

import { readFileSync } from 'node:fs';

/** `[lng, lat]`, in GeoJSON order. */
export type Position = [number, number];
export type Ring = Position[];

export interface PolygonGeometry {
  type: 'Polygon';
  coordinates: Ring[];
}

export interface MultiPolygonGeometry {
  type: 'MultiPolygon';
  coordinates: Ring[][];
}

/** A GeoJSON FeatureCollection whose features are all polygons. */
export interface PolygonCollection {
  type: 'FeatureCollection';
  features: {
    type: 'Feature';
    properties: Record<string, unknown> | null;
    geometry: PolygonGeometry | MultiPolygonGeometry;
  }[];
}

export interface BoundingBox {
  swLat: number;
  swLng: number;
  neLat: number;
  neLng: number;
}

function load(): PolygonCollection {
  const text = readFileSync(new URL('./municipality.geojson', import.meta.url), 'utf8');
  const collection = JSON.parse(text) as PolygonCollection;
  for (const { geometry } of collection.features) {
    const type: string = geometry.type;
    if (type !== 'Polygon' && type !== 'MultiPolygon') {
      throw new Error(`municipality.geojson: unexpected ${type} geometry`);
    }
  }
  return collection;
}

/** `municipality.geojson`: one feature, whose MultiPolygon is the boundary. */
export const MUNICIPALITY_BOUNDARY: PolygonCollection = load();

/** Every ring of every polygon, exterior rings and holes alike. */
function ringsOf(collection: PolygonCollection): Ring[] {
  return collection.features.flatMap(({ geometry }) =>
    geometry.type === 'Polygon' ? geometry.coordinates : geometry.coordinates.flat(),
  );
}

const MUNICIPALITY_RINGS = ringsOf(MUNICIPALITY_BOUNDARY);

/** The smallest box containing every polygon in `collection`. */
export function boundingBox(collection: PolygonCollection): BoundingBox {
  const box = { swLat: Infinity, swLng: Infinity, neLat: -Infinity, neLng: -Infinity };
  for (const ring of ringsOf(collection)) {
    for (const [lng, lat] of ring) {
      box.swLat = Math.min(box.swLat, lat);
      box.swLng = Math.min(box.swLng, lng);
      box.neLat = Math.max(box.neLat, lat);
      box.neLng = Math.max(box.neLng, lng);
    }
  }
  if (box.swLat === Infinity) throw new Error('boundingBox: the collection has no coordinates');
  return box;
}

/** The smallest box containing the boundary. */
export const MUNICIPALITY_BOUNDING_BOX: BoundingBox = boundingBox(MUNICIPALITY_BOUNDARY);

/**
 * Whether a coordinate lies inside `rings`, by even-odd ray casting over
 * every ring, so a polygon's holes count as outside. Coordinates are treated
 * as planar, as GeoJSON and ArcGIS edges are.
 */
export function inRings(rings: readonly Ring[], lat: number, lng: number): boolean {
  let inside = false;
  for (const ring of rings) {
    for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
      const [xi, yi] = ring[i]!;
      const [xj, yj] = ring[j]!;
      if (yi > lat !== yj > lat && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
        inside = !inside;
      }
    }
  }
  return inside;
}

/** Whether a coordinate lies inside the boundary (`inRings`). */
export function inMunicipality(lat: number, lng: number): boolean {
  return inRings(MUNICIPALITY_RINGS, lat, lng);
}
